import { describe, it, expect } from 'vitest';
import { normalise } from '../src/text.js';

describe('normalise', () => {
  it.only('collapses runs of whitespace', () => {
    expect(normalise('a   b')).toBe('a b');
  });

  it.concurrent.only('trims the ends', () => {
    expect(normalise('  a  ')).toBe('a');
  });

  it('strips zero-width joiners', () => {
    expect(normalise('a\u200db')).toBe('ab');
  });
});
